LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B1', 'OpeningCost': '11', 'CoveredDistricts': 'Z1;Z2;Z5'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B2', 'OpeningCost': '14', 'CoveredDistricts': 'Z2;Z3;Z6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B3', 'OpeningCost': '10', 'CoveredDistricts': 'Z4;Z5;Z8'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B4', 'OpeningCost': '13', 'CoveredDistricts': 'Z1;Z6;Z7'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B5', 'OpeningCost': '16', 'CoveredDistricts': 'Z3;Z7;Z9'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B6', 'OpeningCost': '9', 'CoveredDistricts': 'Z8;Z9;Z10'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B7', 'OpeningCost': '12', 'CoveredDistricts': 'Z4;Z10'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/facility_sites.csv', 'values': {'Center': 'B8', 'OpeningCost': '15', 'CoveredDistricts': 'Z5;Z6;Z9'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z1'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z2'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z3'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z4'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z5'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z6'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z7'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z8'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z9'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/benchmark_dataset/Variant14/inputs/service_zones.csv', 'values': {'Zone': 'Z10'}}]
import gurobipy as gp
from gurobipy import GRB
depots = []
opening_cost = {}
depot_covers = {}
zones = set()
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('facility_sites.csv'):
        center = rec['values']['Center']
        depots.append(center)
        opening_cost[center] = float(rec['values']['OpeningCost'])
        covered = [z.strip() for z in rec['values']['CoveredDistricts'].split(';') if z.strip()]
        depot_covers[center] = set(covered)
        zones.update(covered)
zone_list = []
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('service_zones.csv'):
        zone = rec['values']['Zone']
        zone_list.append(zone)
zones = sorted(set(zone_list))
zone_covered_by = {z: [] for z in zones}
for d in depots:
    for z in depot_covers[d]:
        if z in zone_covered_by:
            zone_covered_by[z].append(d)
for z in zones:
    if not zone_covered_by[z]:
        raise ValueError(f'Zone {z} is not covered by any depot.')
m = gp.Model('SetCoveringDepots')
y_vars = m.addVars(depots, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((opening_cost[d] * y_vars[d] for d in depots)), GRB.MINIMIZE)
for z in zones:
    m.addConstr(gp.quicksum((y_vars[d] for d in zone_covered_by[z])) >= 1, name=f'cover_{z}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')